export type AppLanguage = "fi" | "sv" | "en";

/**
 * Translate a Finnish source string into the active language.
 * - Finnish returns the original string unchanged.
 * - If no translation exists, returns the original Finnish (never a wrong language).
 */
export function translateFinnish(finnish: string, language: AppLanguage): string {
  if (language === "fi") return finnish;
  const entry = TRANSLATIONS[finnish];
  if (!entry) return finnish;
  return language === "sv" ? entry.sv : entry.en;
}
